/**
 * The Speaker for a provider, a key and a collaborator's settings. VoiceStudio's "key" is the
 * whole stored connection, and one that will not decode throws.
 *
 * One place that knows every provider, so a route and the worker cannot build them
 * differently: a line regenerated by hand and the same line in a batch must be made alike.
 */
import "server-only";

import type { Preference } from "../preference";
import { decodeConnection } from "../voicestudio-connection";
import { elevenLabsSpeaker } from "./elevenlabs";
import { fishSpeaker } from "./fish";
import { voiceStudioSpeaker } from "./voicestudio";
import type { Provider, Speaker } from "./speaker";

export function speakerFrom(
  provider: Provider,
  apiKey: string,
  preference: Pick<Preference, "elevenlabs" | "fish">,
): Speaker {
  if (provider === "fish") return fishSpeaker({ apiKey, settings: preference.fish });
  if (provider === "voicestudio") return voiceStudioSpeaker(decodeConnection(apiKey));
  return elevenLabsSpeaker({ apiKey, settings: preference.elevenlabs });
}
